#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

#define DISCOVERY_INTERVAL 1000

unsigned long lastDiscovery = 0;

uint8_t carAddress[6];
bool carFound = false;

bool addCarPeer() {
  if (esp_now_is_peer_exist(carAddress)) {
    return true;
  }

  esp_now_peer_info_t peerInfo = {};
  memcpy(peerInfo.peer_addr, carAddress, 6);
  peerInfo.channel = 1;
  peerInfo.encrypt = false;

  return esp_now_add_peer(&peerInfo) == ESP_OK;
}

void onDataReceive(
  const esp_now_recv_info_t *info,
  const uint8_t *data,
  int len
) {
  if (len >= 3 && memcmp(data, "CAR", 3) == 0) {

    memcpy(carAddress, info->src_addr, 6);

    if (addCarPeer()) {
      carFound = true;

      Serial.println();
      Serial.println("==============================");
      Serial.println("CAR FOUND!");
      Serial.println("CONTROLLER AND CAR CONNECTED");
      Serial.println("==============================");
    }
  }
}

void searchForCar() {

  uint8_t broadcastAddress[] = {
    0xFF, 0xFF, 0xFF,
    0xFF, 0xFF, 0xFF
  };

  if (!esp_now_is_peer_exist(broadcastAddress)) {

    esp_now_peer_info_t peerInfo = {};

    memcpy(
      peerInfo.peer_addr,
      broadcastAddress,
      6
    );

    peerInfo.channel = 1;
    peerInfo.encrypt = false;

    esp_now_add_peer(&peerInfo);
  }

  const char hello[] = "HELLO";

  esp_now_send(
    broadcastAddress,
    (uint8_t *)hello,
    sizeof(hello)
  );

  Serial.println("Searching for car...");
}

void setup() {

  Serial.begin(115200);

  WiFi.mode(WIFI_STA);

  esp_wifi_set_channel(
    1,
    WIFI_SECOND_CHAN_NONE
  );

  Serial.println();
  Serial.println("==============================");
  Serial.println("ESP32 CONNECTION TEST");
  Serial.println("==============================");

  Serial.print("Controller MAC: ");
  Serial.println(WiFi.macAddress());

  if (esp_now_init() != ESP_OK) {

    Serial.println("ESP-NOW FAILED!");

    while (true) {
      delay(1000);
    }
  }

  esp_now_register_recv_cb(onDataReceive);

  Serial.println("ESP-NOW READY");
  Serial.println("Searching for car...");
}

void loop() {

  if (!carFound) {

    if (millis() - lastDiscovery >= DISCOVERY_INTERVAL) {

      lastDiscovery = millis();

      searchForCar();
    }
  }

  delay(10);
}
